/* ---------- Workspace rail ---------- */
.wrx{display:flex;min-height:330px;overflow:hidden}
.wrx-rail{width:56px;flex:none;display:flex;flex-direction:column;gap:2px;padding:10px 9px;border-right:1px solid var(--line);transition:width .5s var(--ease);overflow:hidden}
.wrx.wide .wrx-rail{width:188px}
.wrx-ws{display:flex;align-items:center;gap:10px;padding:2px 2px 10px;white-space:nowrap}
.wrx-lg .logo{width:20px;height:20px}
.wrx-lg{width:34px;height:34px;border-radius:11px;background:var(--ink);color:var(--on-ink);display:grid;place-items:center;font-weight:500;flex:none}
.wrx-lb{white-space:nowrap;opacity:0;transform:translateX(-6px);filter:blur(3px);transition:opacity .3s,transform .45s var(--ease),filter .3s;display:flex;flex-direction:column;font-size:13px;line-height:1.3}
.wrx-lb .muted{font-size:11.5px}
.wrx.wide .wrx-lb{opacity:1;transform:none;filter:none;transition-delay:.08s}
.wrx-nav{display:flex;flex-direction:column;gap:2px;position:relative}
.wrx-ind{position:absolute;left:0;right:0;height:36px;border-radius:11px;background:var(--chip);transition:top .45s var(--ease);top:0}
.wrx-i{position:relative;display:flex;align-items:center;gap:12px;height:36px;padding:0 10px;border-radius:11px;color:var(--fg2);white-space:nowrap;transition:color .2s}
.wrx-i:hover{color:var(--fg)}
.wrx-i.on{color:var(--fg)}
.wrx-i .bd{position:absolute;left:19px;top:4px;min-width:15px;height:15px;padding:0 4px;border-radius:8px;background:var(--accent);color:#fff;font-size:9.5px;font-weight:500;display:grid;place-items:center;box-shadow:0 0 0 2px var(--surface)}
.wrx-i .wrx-lb{flex-direction:row}
.wrx-sp{flex:1}
.wrx-runs{display:flex;flex-direction:column;gap:2px;margin-bottom:6px}
.wrx-lbh{font-size:11px;color:var(--muted);padding:0 10px 4px;opacity:0;height:0;overflow:hidden;transition:opacity .3s}
.wrx.wide .wrx-lbh{opacity:1;height:auto}
.wrx-run{display:flex;align-items:center;gap:12px;height:32px;padding:0 11px;border-radius:10px;font-size:12.5px;color:var(--fg2);white-space:nowrap}
.wrx-run:hover{background:var(--row)}
.wrx-run .think{color:var(--accent)}
.wrx-pin svg{transition:transform .5s var(--ease)}
.wrx.wide .wrx-pin svg{transform:scaleX(-1)}
.wrx-main{flex:1;min-width:0;padding:18px;display:flex;flex-direction:column;gap:14px}
.wrx-mh{font-size:14px;font-weight:500}
.wrx-sk{display:flex;flex-direction:column;gap:9px}
.wrx-sk i{display:block;height:9px;border-radius:5px;background:var(--chip)}
.wrx-sk i.b{height:120px;width:100%;border-radius:14px;margin-top:6px}

DM.def('workspace-rail', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{panel}', I('panel'));
  const N = [['home','Home',0],['spark','Agent',2],['layers','Projects',0],['figma','Frames',0],['book','Memory',0],['gear','Settings',0]];
  const nav = $('.wrx-nav', r), ind = $('.wrx-ind', r), root = $('.wrx', r), mh = $('.wrx-mh', r);
  nav.insertAdjacentHTML('beforeend', N.map((n, i) => `<button class="wrx-i${i === 1 ? ' on' : ''}" data-i="${i}" aria-label="${n[1]}" data-tip="${n[1]}">${I(n[0])}${n[2] ? `<span class="bd">${n[2]}</span>` : ''}<span class="wrx-lb">${n[1]}</span></button>`).join(''));
  $('.wrx-runs', r).insertAdjacentHTML('beforeend', ['Pricing audit','Token export'].map(t => `<button class="wrx-run" data-tip="${t}"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="wrx-lb">${t}</span></button>`).join(''));
  const items = $$('.wrx-i[data-i]', nav);
  function go(b){ items.forEach(x => x.classList.toggle('on', x === b)); ind.style.top = b.offsetTop + 'px'; swap(mh, N[+b.dataset.i][1]); const bd = $('.bd', b); if (bd){ bd.classList.add('leave'); c.later(300, () => bd.remove()); } }
  items.forEach(b => b.onclick = () => go(b));
  const tipSync = () => $$('[data-tip]', $('.wrx-rail', r)).forEach(el => { if (!el.dataset.t0) el.dataset.t0 = el.dataset.tip; if (root.classList.contains('wide') && !el.classList.contains('wrx-pin')) el.removeAttribute('data-tip'); else el.dataset.tip = el.dataset.t0; });
  $('.wrx-pin', r).onclick = () => { root.classList.toggle('wide'); const w = root.classList.contains('wide'); $('.wrx-pin', r).dataset.t0 = w ? 'Collapse' : 'Pin open'; tipSync(); };
  mh.textContent = 'Agent'; requestAnimationFrame(() => ind.style.top = items[1].offsetTop + 'px');
  c.later(1500, () => { root.classList.add('wide'); $('.wrx-pin', r).dataset.t0 = 'Collapse'; tipSync(); });
});
